-- imna.zoek_gebied_klimaat

CREATE TABLE imna.zoek_gebied_klimaat
(
	id bigint NOT NULL   DEFAULT NEXTVAL(('imna_seq'::text)::regclass),    -- Internal ID of the climate search area
	identificatie char(100) NOT NULL,    -- External ID of the climate search area
	begin_geldigheid timestamp NOT NULL,    -- Start of the validity for this version of the climate search area
	eind_geldigheid timestamp NULL,    -- End of the validity for this version of the climate search area
	begin_tijd timestamp NULL,    -- Start of the validity for this version of the climate search area identified by the idenficatie and provinceId
	eind_tijd timestamp NULL,    -- End of the validity for this version of the climate search area identified by the idenficatie and provinceId
	nbp_id bigint NOT NULL,    -- Id linking to the Nature Maintenance Plan use to submit this version of the climate search area
	status_id bigint NOT NULL,    -- Domain Id linking to the status of the climate search area
	provincie_id bigint NOT NULL,    -- Domain id linking to the province who is responsible for the climate search area
	deelgebied_id bigint NULL,    -- Domain id linking to the sub-area that is associated with the climate search area. As sub-areas are specified per province the reference is to the link-table.
	geom geometry NOT NULL,    -- Geometry single polygon in EPSG:28992 of the climate search area
	klimaat_natuur_type_id bigint NOT NULL,    -- Domain id linking to the agricultural climate type of the climate search area
	naam char(100) NULL    -- name of the climate search area
)
;

